import data from "./data/ledger.json";
import type { RunLine } from "./runlog";

/**
 * The robot's "done" across every live night, from the evidence ledger (jury round 3, item C2).
 * `data/ledger.json` is generated by `scripts/ledger.py` from the live run logs, next to
 * docs/runs/ledger.csv; nothing here is typed in by hand. A night counts when its log was found and
 * the robot reported at least one "done" in it.
 */

export type LedgerNight = {
  shift: string;
  started: string;
  seed: number | null;
  commit: string;
  complete: boolean;
  score: number | null;
  done_reports: number | null;
  done_credited: number | null;
  declines_credited: number | null;
  declines_not_credited: number | null;
};

export const LEDGER_NIGHTS: readonly LedgerNight[] = data.nights as LedgerNight[];

export type Precision = {
  nights: number;
  reported: number;
  credited: number;
  /** One decimal; never rounds up to 100 while one "done" was not credited. */
  percent: number;
};

/** Credited "done" over reported "done" for `nights`; null when none of them reported a "done". */
export function precision(nights: readonly LedgerNight[]): Precision | null {
  const counted = nights.filter((night) => (night.done_reports ?? 0) > 0);
  const reported = counted.reduce((sum, night) => sum + (night.done_reports ?? 0), 0);
  const credited = counted.reduce((sum, night) => sum + (night.done_credited ?? 0), 0);
  if (reported === 0) return null;
  let percent = Math.round((credited / reported) * 1000) / 10;
  if (credited < reported) percent = Math.min(percent, 99.9);
  return { nights: counted.length, reported, credited, percent };
}

/** The shift id on the log's `start` line. */
export function shiftOf(lines: readonly RunLine[]): string | null {
  const start = lines.find((line) => line.type === "start");
  return start?.type === "start" ? start.shift : null;
}

export type CrossNight = {
  /** Every live night in the ledger. */
  all: Precision | null;
  /** The nights played by the same build (commit) as the night on screen; null when the ledger does not know it. */
  build: (Precision & { commit: string }) | null;
};

/** The whole ledger, and the build that played `shift`. */
export function crossNightPrecision(shift: string | null, nights: readonly LedgerNight[] = LEDGER_NIGHTS): CrossNight {
  const all = precision(nights);
  const commit = shift ? nights.find((night) => night.shift === shift)?.commit : undefined;
  const same = commit ? precision(nights.filter((night) => night.commit === commit)) : null;
  return { all, build: same && commit ? { ...same, commit } : null };
}

/** "4 340" (a thin non-breaking space, as Norwegian figures are grouped). */
export function grouped(n: number): string {
  return n.toLocaleString("nb-NO").replace(/\s/g, " ");
}

/** "99,2 %". */
export function percentText(percent: number): string {
  return `${percent.toLocaleString("nb-NO", { minimumFractionDigits: 1, maximumFractionDigits: 1 })} %`;
}
